CREATE TABLE advertising_campaigns (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), seller_id UUID NOT NULL REFERENCES users(id), product_id UUID REFERENCES products(id), campaign_type TEXT NOT NULL CHECK(campaign_type IN ('SPONSORED_PRODUCT','SPONSORED_SEARCH','BANNER','CATEGORY_PROMOTION','SHOP_PROMOTION')), pricing_model TEXT NOT NULL DEFAULT 'FIXED_PRICE', budget BIGINT NOT NULL CHECK(budget>=0), spent BIGINT NOT NULL DEFAULT 0 CHECK(spent>=0 AND spent<=budget), status TEXT NOT NULL DEFAULT 'DRAFT', start_at TIMESTAMPTZ, end_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX advertising_campaigns_seller_idx ON advertising_campaigns(seller_id,status);
